55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	  rune: 25,
65	} as const satisfies Record<string, number>;
66	
67	type InsurableItemType = keyof typeof BASE_PREMIUMS;
68	
69	const basePremiumFor = (itemType: string): number =>
70	  BASE_PREMIUMS[itemType as InsurableItemType];
71	
72	const basePremiumForItems = (items: Item[]): number =>
73	  items.reduce((sum, item) => sum + basePremiumFor(item.type), 0);
74	
75	const withInitialAssessmentSurcharge = (basePremium: number): number =>
76	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
77	
78	const quotePremium = (items: Item[]): number =>
79	  Math.round(
80	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
81	  );
82	
83	const runStep = (step: Step): StepResult => {
84	  if (step.op === "quote") return { premium: quotePremium(step.items) };
85	  throw new Error(`Unsupported step: ${step.op}`);
86	};
87	
88	export const runScenario = (scenario: Scenario): ScenarioResult => ({
89	  results: scenario.steps.map(runStep),
90	});
